const $=id=>document.getElementById(id),pick=a=>a[Math.random()*a.length|0],sh=a=>a.map(x=>[Math.random(),x]).sort((p,q)=>p[0]-q[0]).map(p=>p[1]);
let name=PROFILE;try{const v=localStorage.getItem('fname');if(v!==null)name=v||PROFILE}catch(e){}
const NICK=['فاطمة','فطومة','فطم','فطومتي'];const who=()=>(!name||name==='فاطمة')?pick(NICK):name;
function greet(){$('hi').textContent='هلا بيج'+(name?' يا '+name:'')+'، نورتي ✨';$('nm').value=name}
$('setnm').onclick=()=>{name=$('nm').value.trim();try{localStorage.setItem('fname',name)}catch(e){}greet();$('go').textContent='يلا '+who()+'، خمّني!'};
