const T=[['home','🏠 الرئيسية'],['games','🎮 ألعاب'],['brain','🧠 ألغاز'],['poems','📜 شعر'],['fun','😂 ضحك'],['stuff','🎲 أشياء'],['love','🤫 تلميحات'],['dhikr','🕌 أذكار'],['study','📚 الدراسة'],['care','🧴 العناية'],['kitchen','🍳 المطبخ'],['habit','🌱 عاداتي'],['iraq','🇮🇶 العراق'],['girls','🌸 للبنات'],['more','⭐ زيادة']];
T.forEach((t,i)=>{const b=document.createElement('button');b.textContent=t[1];if(!i)b.className='on';b.onclick=()=>{[...$('tabs').children].forEach(x=>x.classList.toggle('on',x===b));T.forEach(s=>$(s[0]).classList.toggle('hide',s[0]!==t[0]))};$('tabs').append(b)});
function cyc(arr,el,btn,fmt){let l=-1;const f=()=>{let i;do{i=Math.random()*arr.length|0}while(i===l&&arr.length>1);l=i;$(el).textContent=fmt?fmt(arr[i]):arr[i]};$(btn).onclick=f;f()}

// خمّن الرقم
