$('gb').onclick=()=>{const v=+$('gn').value;if(!v||v<1||v>100){$('go').textContent='اكتبي رقم من ١ لـ ١٠٠ '+who();return}tr++;
$('go').textContent=v===sec?'عاشت! 🎉 طلعتيها بـ '+tr+' محاولات':v<sec?'اكبر شوية ⬆️':'اصغر شوية ⬇️'};
