document.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{const m=+b.dataset.r,c=Math.random()*3|0;let t='تعادل 😅';
if(m!==c){if((m+1)%3===c){t='خسرتي، لا تزعلين 😎';s2++}else{t='عاشت، فزتي 👏';s1++}}
$('ro').textContent='انت: '+rn[m]+' | اني: '+rn[c]+' — '+t;$('rs1').textContent=s1;$('rs2').textContent=s2});

// إكس أو
let xb,xd;const WL=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
const xw=p=>WL.some(l=>l.every(i=>xb[i]===p));
function xdraw(){$('xo').innerHTML='';xb.forEach((v,i)=>{const b=document.createElement('button');b.className='cell';b.textContent=v;b.onclick=()=>xplay(i);$('xo').append(b)})}
function xnew(){xb=Array(9).fill('');xd=false;$('xs').textContent='انت X، وإني O. ابدي!';xdraw()}
let XT=[0,0,0];const xtt=()=>$('xsc').textContent='انت '+XT[0]+' | اني '+XT[1]+' | تعادل '+XT[2];
function xend(){if(xw('X')){$('xs').textContent='فزتي عليّ! عاشت 👏';XT[0]++;xtt();return xd=true}if(xw('O')){$('xs').textContent='فزت عليج 😎';XT[1]++;xtt();return xd=true}if(xb.every(v=>v)){$('xs').textContent='تعادل 🤝';XT[2]++;xtt();return xd=true}return false}
function xplay(i){if(xd||xb[i])return;xb[i]='X';if(xend())return xdraw();
let mv=null;for(const p of['O','X']){for(let k=0;k<9&&mv===null;k++)if(!xb[k]){xb[k]=p;if(xw(p))mv=k;xb[k]=''}}
if(mv===null)mv=xb[4]?pick([0,1,2,3,4,5,6,7,8].filter(k=>!xb[k])):4;xb[mv]='O';xend();xdraw()}
$('xr').onclick=xnew;xnew();

// ذاكرة
let mc,mo,mf,mn;
function mnew(){const ME=[...'🍉🌴🐪☕🎯🌙🍯🚀'];mc=sh([...ME,...ME]);mo=[];mf=0;mn=0;$('ms').textContent='لگي الأزواج!';$('mm').innerHTML='';
mc.forEach((e,i)=>{const b=document.createElement('button');b.className='cell';b.onclick=()=>{if(b.textContent||mo.length>1)return;b.textContent=e;b.classList.add('up');mo.push([b,e]);
if(mo.length===2){mn++;if(mo[0][1]===mo[1][1]){mo.forEach(x=>x[0].className='cell done');mo=[];if(++mf===8)$('ms').textContent='خلصتها بـ '+mn+' محاولة، عاشت! 🎉'}
else setTimeout(()=>{mo.forEach(x=>{x[0].textContent='';x[0].className='cell'});mo=[]},700)}};$('mm').append(b)})}
