const hCells=[];for(let i=0;i<9;i++){const b=document.createElement('button');b.className='cell';b.onclick=()=>{if(hI&&i===hP){hS++;b.textContent='💥';hP=-1;$('hs2').textContent='النقاط: '+hS+' | الوقت: '+hT}};hCells.push(b);$('hg').append(b)}
function hmove(){hCells.forEach(c=>c.textContent='');hP=Math.random()*9|0;hCells[hP].textContent='🐪'}
function hend(){clearInterval(hI);clearInterval(hC);hI=null;hCells.forEach(c=>c.textContent='');hP=-1;let m='خلص الوقت! صدتي '+hS+' جمل';if(hS>hB){hB=hS;try{localStorage.setItem('hbest',hB)}catch(e){}m+=' 🎉 رقم قياسي جديد'}$('hs2').innerHTML=m+' | أفضل نتيجة: <span class="sc">'+hB+'</span>';$('hgo').textContent='ابدأ من جديد'}
$('hgo').onclick=()=>{if(hI)return;hS=0;hT=20;$('hgo').textContent='...';$('hs2').textContent='النقاط: 0 | الوقت: 20';hmove();hI=setInterval(hmove,533);hC=setInterval(()=>{hT--;$('hs2').textContent='النقاط: '+hS+' | الوقت: '+hT;if(hT<=0)hend()},1000)};

