const scn=x=>x.replace(/[\u064B-\u065F\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/گ/g,'ك').replace(/چ/g,'ج').replace(/\s+/g,'').trim();
