function scnew(){let i;do{i=Math.random()*SCW.length|0}while(i===scL);scL=i;scC=SCW[i];let a;const ch=[...scC[0]];do{a=sh(ch)}while(a.join('')===scC[0]);$('scw').textContent=a.join(' ');$('sch').textContent='تلميح: '+scC[1];$('sci').value='';$('sco').textContent=''}
$('scb').onclick=()=>{const v=scn($('sci').value);if(!v){$('sco').textContent='اكتبي الكلمة أول';return}if(v===scn(scC[0])){scP++;$('scs').textContent=scP;$('sco').textContent='صح! عاشت 🎉 الكلمة: '+scC[0];$('sco').style.color='var(--ok)'}else{$('sco').textContent='لا، حاولي مرة ثانية 😅';$('sco').style.color=''}};
