// لوحة رسم
const dp=$('dp'),dx=dp.getContext('2d');let dr=false;dx.lineWidth=4;dx.lineCap='round';
const dpos=e=>{const r=dp.getBoundingClientRect(),t=e.touches?e.touches[0]:e;return[(t.clientX-r.left)*400/r.width,(t.clientY-r.top)*260/r.height]};
const ds=e=>{dr=true;const[x,y]=dpos(e);dx.beginPath();dx.moveTo(x,y);dx.strokeStyle=$('dc').value;e.preventDefault()},dm=e=>{if(!dr)return;const[x,y]=dpos(e);dx.lineTo(x,y);dx.stroke();e.preventDefault()};
['mousedown','touchstart'].forEach(v=>dp.addEventListener(v,ds,{passive:false}));['mousemove','touchmove'].forEach(v=>dp.addEventListener(v,dm,{passive:false}));['mouseup','mouseleave','touchend'].forEach(v=>dp.addEventListener(v,()=>dr=false));
