adh('a5',[['عند دخول البيت: بسم الله ولجنا، وبسم الله خرجنا، وعلى الله ربنا توكلنا',''],['عند الخروج: بسم الله، توكلت على الله، ولا حول ولا قوة إلا بالله',''],['قبل الأكل: بسم الله',''],['بعد الأكل: الحمد لله الذي أطعمني هذا ورزقنيه من غير حول مني ولا قوة','']]);
adh('a6',[['لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم',''],['اللهم إني أعوذ بك من الهم والحزن، والعجز والكسل، والبخل والجبن، وضلع الدين وغلبة الرجال',''],['لا إله إلا أنت سبحانك إني كنت من الظالمين',''],['حسبنا الله ونعم الوكيل','']]);
