adh('a9',[['ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار',''],['ربنا لا تؤاخذنا إن نسينا أو أخطأنا',''],['رب ارحمهما كما ربياني صغيرًا','للوالدين'],['ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا','']]);
const DD=[['رب زدني علمًا','للعلم والدراسة'],['حسبنا الله ونعم الوكيل','عند الضيق'],['اللهم إني أعوذ بك من الهم والحزن','للهم والحزن'],['ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار','دعاء جامع'],['رب اشرح لي صدري ويسر لي أمري','قبل الامتحان'],['اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري','للعافية'],['بسم الله توكلت على الله ولا حول ولا قوة إلا بالله','عند الخروج'],['رب ارحمهما كما ربياني صغيرًا','للوالدين'],['اللهم عجل لوليك الفرج','دعاء الفرج'],['اللهم صل على محمد وآل محمد','صلاة على النبي وآله']];
