const OCC=[[1,1,'رأس السنة الهجرية'],[1,10,'يوم عاشوراء: استشهاد الإمام الحسين (ع)'],[2,20,'أربعينية الإمام الحسين (ع)'],[2,28,'وفاة النبي (ص) واستشهاد الإمام الحسن (ع)'],[3,17,'مولد النبي (ص) ومولد الإمام الصادق (ع)'],[6,20,'ولادة السيدة فاطمة الزهراء (ع)'],[7,13,'ولادة الإمام علي (ع)'],[7,27,'المبعث النبوي'],[8,3,'ولادة الإمام الحسين (ع)'],[8,4,'ولادة أبي الفضل العباس (ع)'],[8,15,'ولادة الإمام المهدي (عج)'],[9,15,'ولادة الإمام الحسن (ع)'],[9,21,'استشهاد الإمام علي (ع)'],[12,18,'عيد الغدير']];
function occR(){$('ocL').innerHTML='';try{const f=new Intl.DateTimeFormat('en-u-ca-islamic-civil',{day:'numeric',month:'numeric'}),t=new Date();t.setHours(12,0,0,0);const r={};
for(let i=0;i<400;i++){const d=new Date(t);d.setDate(t.getDate()+i);const p=f.formatToParts(d),m=+p.find(x=>x.type==='month').value,dd=+p.find(x=>x.type==='day').value;OCC.forEach((o,k)=>{if(o[0]===m&&o[1]===dd&&!(k in r))r[k]=[i,d]})}
let h='';try{h=new Intl.DateTimeFormat('ar-IQ-u-ca-islamic-civil',{day:'numeric',month:'long',year:'numeric'}).format(t)}catch(e){}
$('ocH').textContent=h?'تاريخ اليوم الهجري: '+h:'';
Object.values(r).sort((a,b)=>a[0]-b[0]).length;
Object.keys(r).sort((a,b)=>r[a][0]-r[b][0]).slice(0,7).forEach(k=>{const d=document.createElement('div');d.className='out';d.textContent=OCC[k][2]+' — '+(r[k][0]===0?'اليوم':'بعد '+r[k][0]+' يوم')+' ('+r[k][1].toLocaleDateString('ar-IQ',{day:'numeric',month:'long'})+')';$('ocL').append(d)})}catch(e){$('ocL').textContent='المتصفح ما يدعم حساب التقويم الهجري هنا'}}
occR();document.addEventListener('visibilitychange',()=>{if(!document.hidden)occR()});setInterval(occR,3600000);
