function mdr(){const t=new Date();$('mdL').innerHTML='';for(let i=6;i>=0;i--){const d=new Date(t);d.setDate(t.getDate()-i);const e=MO[dkey(d)]||'·';const x=document.createElement('span');x.style.cssText='display:inline-block;min-width:3.2em;text-align:center;margin:2px';x.textContent=d.toLocaleDateString('ar-IQ',{weekday:'short'})+' '+e;$('mdL').append(x)}}
['😄','🙂','😐','😔','😡'].forEach(e=>{const b=document.createElement('button');b.textContent=e;b.style.fontSize='1.5rem';b.onclick=()=>{MO[dkey(new Date())]=e;try{localStorage.setItem('moods2',JSON.stringify(MO))}catch(x){}mdr()};$('mdB').append(b)});mdr();

// للبنات
function h2l(x){const r=parseInt(x.substr(1,2),16)/255,g=parseInt(x.substr(3,2),16)/255,b=parseInt(x.substr(5,2),16)/255,mx=Math.max(r,g,b),mn=Math.min(r,g,b);let h=0,sa=0;const l=(mx+mn)/2;if(mx!==mn){const d=mx-mn;sa=l>.5?d/(2-mx-mn):d/(mx+mn);h=(mx===r?(g-b)/d+(g<b?6:0):mx===g?(b-r)/d+2:(r-g)/d+4)*60}return[h,sa*100,l*100]}
function l2h(h,sa,l){h=((h%360)+360)%360;sa/=100;l/=100;const k=n=>(n+h/30)%12,a=sa*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1))),x=v=>Math.round(v*255).toString(16).padStart(2,'0');return '#'+x(f(0))+x(f(8))+x(f(4))}
function sw(c,dark){const d=document.createElement('div');d.style.cssText='flex:1;min-width:68px;height:52px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:.78rem;border:2px solid var(--line);background:'+c+';color:'+(dark?'#fff':'#222');d.textContent=c;return d}
function gcr(){const[h,sa,l]=h2l($('gcI').value),dk2=l<60;$('gcO').innerHTML='';[['ألوان مجاورة (هادية)',[h-30,h,h+30]],['اللون المقابل (جريء)',[h,h+180]],['ثلاثي متوازن',[h,h+120,h+240]]].forEach(g=>{const t=document.createElement('div');t.textContent=g[0];t.style.margin='8px 0 2px';const r=document.createElement('div');r.className='row';g[1].forEach(x=>r.append(sw(l2h(x,sa,l),dk2)));$('gcO').append(t,r)});const t=document.createElement('div');t.textContent='ألوان محايدة تنسجم مع الكل';t.style.margin='8px 0 2px';const r=document.createElement('div');r.className='row';['#ffffff','#f5efe6','#d9c9b0','#9a9a9a','#222222'].forEach((c,i)=>r.append(sw(c,i>2)));$('gcO').append(t,r)}
$('gcI').oninput=gcr;gcr();
const OF={'جامعة':['بنطلون مستقيم وقميص فضفاض وحذاء مريح','تنورة طويلة وبلوزة بسيطة وسترة خفيفة','فستان عملي بقماش مريح وحقيبة تسع الكتب'],'طلعة':['جينز مرتب وبلوزة بلون هادي وإكسسوار بسيط','فستان خفيف ومعاه جاكيت جينز','تنسيق لونين محايدين مع قطعة لافتة وحدة'],'مناسبة':['فستان بلون راقي وإكسسوار واحد بس','طقم متناسق بقماش ناعم وحذاء مريح تقدرين تمشين بيه','لون غني (مثل الأخضر الغامق أو النبيذي) مع إضافات ذهبية خفيفة'],'بالبيت':['ملابس قطن مريحة وجوارب دافية','طقم بيجاما ناعم بلون تحبينه','سويت شيرت واسع وشورت أو بنطلون خفيف']};
$('ofB').onclick=()=>$('ofO').textContent='👗 '+pick(OF[$('ofS').value]);
let PD=null;try{PD=JSON.parse(localStorage.getItem('period')||'null')}catch(e){}
if(PD){$('pdD').value=PD.d;$('pdL').value=PD.l}
$('pdB').onclick=()=>{const v=$('pdD').value,len=Math.min(45,Math.max(20,parseInt($('pdL').value)||28));if(!v){$('pdO').textContent='اختاري تاريخ أول يوم بآخر دورة';return}try{localStorage.setItem('period',JSON.stringify({d:v,l:len}))}catch(e){}
const t=new Date();t.setHours(0,0,0,0);let n=new Date(v+'T00:00:00');while(n<t)n.setDate(n.getDate()+len);const f=d=>d.toLocaleDateString('ar-IQ',{weekday:'long',day:'numeric',month:'long'}),n2=new Date(n);n2.setDate(n2.getDate()+len);const k=Math.round((n-t)/864e5);
$('pdO').textContent='الدورة المتوقعة: '+f(n)+(k===0?' (اليوم)':' (بعد '+k+' يوم)')+'، والتي بعدها حوالي '+f(n2)+(len<21||len>35?'. طول دورتج خارج المعتاد (٢١–٣٥ يوم)، فيستحسن تستشيرين طبيبة.':'')};
const WK=['تسخين ٥ دقايق: مشي بمكانج ودوران الأكتاف وتحريك المفاصل','سكوات ١٢ مرة','لانجز ١٠ مرات لكل رجل','جسر الأرداف ١٢ مرة','بلانك ٢٠–٣٠ ثانية','ضغط على الركب ٨–١٠ مرات','قفز (جامبينغ جاك) ٣٠ ثانية، وتخطينه إذا فيج ألم بالمفاصل','إطالة ٥ دقايق'];
WK.forEach(t=>{const b=document.createElement('button');b.className='opt';b.style.margin='3px 0';b.textContent='⬜ '+t;b.onclick=()=>{const d=b.classList.toggle('r');b.textContent=(d?'✅ ':'⬜ ')+t};$('wkL').append(b)});
const wkn=document.createElement('div');wkn.style.cssText='color:var(--soft);font-size:.85rem;margin-top:6px';wkn.textContent='وقفي إذا حسيتي بألم أو دوخة. وإذا عندج مشكلة صحية أو حمل أو إصابة، استشيري طبيبة قبل ما تبدين.';$('wkL').append(wkn);
const GF={'عيد ميلاد':['دفتر يوميات حلو مع قلم','باقة ورد صغيرة وبطاقة مكتوبة بخطج','عطر أو كريم يدين بحجم صغير','كوب شخصي باسمها','صورة مؤطرة من ذكرى حلوة'],'تخرج':['قلم أنيق ومفكرة','باقة ورد مع شهادة تقدير مكتوبة','حقيبة عملية','كتاب تحبه','إطار صورة التخرج'],'نجاح':['شوكولاتة وورد','بطاقة تهنئة بخطج','فنجان چاي أنيق','عشاء أو طلعة تعزمينها عليها'],'هدية بسيطة':['وردة وبطاقة صغيرة','شوكولاتة','ربطة شعر حلوة','مشروب من كافيهها المفضل','رسالة كتبتيها بإيدج']};
