// الرئيسية
const HQ=['خطوة صغيرة اليوم أحسن من خطة كبيرة بكرة','ابتسامة وحدة تغيّر يوم كامل','اللي يبدأ يوصل','خذي نفس عميق وكملي','اليوم فرصة جديدة','شوية صبر وتلگين الفرج','سوّي اللي عليج والباقي على الله'];
function tgo(id){const i=T.findIndex(x=>x[0]===id);if(i>=0)$('tabs').children[i].click();window.scrollTo({top:0,behavior:'smooth'})}
T.filter(x=>x[0]!=='home').forEach(x=>{const b=document.createElement('button');b.className='opt';b.style.margin='0';b.textContent=x[1];b.onclick=()=>tgo(x[0]);$('hmG').append(b)});
$('hmF').oninput=()=>{const q=nz($('hmF').value.trim());[...$('hmG').children].forEach(b=>b.style.display=nz(b.textContent).includes(q)?'':'none')};
function hms(){$('hmD').textContent=new Date().toLocaleDateString('ar-IQ',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+($('ocH').textContent?' — '+$('ocH').textContent.replace('تاريخ اليوم الهجري: ',''):'');
$('hmQ').textContent='✨ '+pick(HQ);const td=dkey(new Date()),hv=Object.keys(HB),hd=hv.filter(h=>HB[h].includes(td)).length,oc=$('ocL').firstChild?$('ocL').firstChild.textContent:'';
const L=['💧 الماي: '+WT.n+'/8','✅ المهام: '+TD.filter(t=>t.d).length+'/'+TD.length,'🌱 العادات: '+hd+'/'+hv.length,'🙂 المزاج: '+(MO[td]||'لسه ما اخترتي')];if(oc)L.push('📅 '+oc);
$('hmS').innerHTML='';L.forEach(t=>{const d=document.createElement('div');d.textContent=t;d.style.margin='4px 0';$('hmS').append(d)})}
let EV=null;try{EV=JSON.parse(localStorage.getItem('event')||'null')}catch(e){}
function evr(){if(!EV){$('evO').textContent='';return}$('evN').value=EV.n;$('evD').value=EV.d;const t=new Date();t.setHours(0,0,0,0);const k=Math.round((new Date(EV.d+'T00:00:00')-t)/864e5);$('evO').textContent=k>0?'باقي '+k+' يوم على '+EV.n:k===0?'اليوم! '+EV.n:'مرّ '+(-k)+' يوم على '+EV.n}
$('evB').onclick=()=>{const n=$('evN').value.trim(),d=$('evD').value;if(!n||!d){$('evO').textContent='اكتبي اسم الحدث واختاري التاريخ';return}EV={n,d};try{localStorage.setItem('event',JSON.stringify(EV))}catch(e){}evr()};
evr();hms();$('tabs').children[0].addEventListener('click',hms);setInterval(hms,3600000);


